import{z as n,x as o,o as e,c as m,q as A,j as B,D as E,d as t,s as i,S as r,b as l}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"内存访问模式分析","description":"","frontmatter":{"title":"内存访问模式分析","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-memory-access.md","filePath":"llm/ak-memory-access.md","lastUpdated":1791063341000}'),d={name:"llm/ak-memory-access.md"};function h(p,a,D,c,F,C){const s=o("Mermaid");return e(),m("div",null,[a[2]||(a[2]=A('<h1 id="内存访问模式分析" tabindex="-1">内存访问模式分析 <a class="header-anchor" href="#内存访问模式分析" aria-label="Permalink to &quot;内存访问模式分析&quot;">​</a></h1><div class="epigraph"><p>内核快慢的账本记在字节上：谁在什么时候从哪一层存储搬了多少字节，比 FLOPs 表更接近真相。</p><footer>—— 据 Williams et al., Roofline, 2009；Dao et al., FlashAttention, 2022 整理</footer></div><p><a href="/llm/ak-flashattention-reread">上一课</a>把 tiling 与 online softmax 装进了内核骨架，收在「省的是字节」。本课把这句直觉拆成可测量的账：访存模式分析。后面谈片上预算、各路变体的内核与基准方法论，都要先会记这本账——记错账的优化，到测速那天全是事故。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一个注意力内核，前填八千 tokens 是算力活，小 batch 解码却是搬运活。判据是算术强度 \\(I=\\mathrm{FLOPs}/\\mathrm{bytes}\\) 对上机器的平衡点：低于它，计算单元在等数据，减 FLOPs 的任何努力都兑不成时间，见<a href="/llm/arithmetic-intensity-decode">解码的算术强度</a>。缺口有两层。第一层是账目：这个内核每跑一步，逻辑上必须移动哪些字节。第二层是质量：同样一个字节，合并访问一次搬走与拆成三十二条事务，在带宽表上差出一个数量级。只看 FLOPs 或只看代码逻辑，两层的错都看不出来。</p><p><span class="marginnote">术语翻译：算术强度就是「每搬 1 字节能做几次运算」。它低于机器平衡点时，计算单元大部分时间在干等数据送来——这时优化算法，等于给一个等外卖的人换一口更快的锅。</span></p><h3 id="必搬、合并、复用-三本账" tabindex="-1">必搬、合并、复用：三本账 <a class="header-anchor" href="#必搬、合并、复用-三本账" aria-label="Permalink to &quot;必搬、合并、复用：三本账&quot;">​</a></h3><p>必搬的账按算法定：权重、激活、KV，与实现无关。合并的账按布局定：warp 内三十二个线程若触到连续地址，硬件并成一次事务；跨步、转置、逐头散布的布局把它拆碎。复用的账按层级定：一个数据被用第二次时，它驻在寄存器、SRAM 还是 L2，决定要不要再过 HBM。</p><p><span class="marginnote">直觉类比：合并访问像一辆班车沿街按顺序接 32 个人，一趟接完；不合并的访问像 32 个人各叫一辆出租车，去的是相邻门牌——路没变，车次翻了 32 倍，路就堵死了。布局决定坐不坐班车。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三步记账法。第一步列必搬字节：解码一步至少要读全部权重与全部 KV，写出 \\(n_q\\times d\\) 的输出；前填还要读写激活。第二步检查合并：KV 沿序列维顺序读时，\\([\\mathrm{batch},h,n,d]\\) 与 \\([n,h,d]\\) 两种布局的地址模式完全不同，解码内核偏爱后者；载入 \\(K,V\\) 块时按 \\(d\\) 维连续，warp 内相邻线程触相邻元素。第三步检查复用层级：FlashAttention 的核心就是让 \\(Q\\) 块驻留片上、被整组 KV 块复用，复用发生在 SRAM 而不是碰运气的 L2。</p>',11)),(e(),B(r,null,{default:E(()=>[i(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%88%97%E5%BF%85%E6%90%AC%E5%AD%97%E8%8A%82%EF%BC%9A%E6%9D%83%E9%87%8D%E3%80%81KV%E3%80%81%E6%BF%80%E6%B4%BB%22%5D%20--%3E%20B%5B%22%E6%9F%A5%E5%90%88%E5%B9%B6%EF%BC%9A%E5%B8%83%E5%B1%80%E4%B8%8E%20warp%20%E5%9C%B0%E5%9D%80%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%9F%A5%E5%A4%8D%E7%94%A8%E5%B1%82%E7%BA%A7%EF%BC%9A%E5%AF%84%E5%AD%98%E5%99%A8%E3%80%81SRAM%E3%80%81L2%22%5D%0A%20%20C%20--%3E%20D%7B%22I%20%E4%BD%8E%E4%BA%8E%E6%9C%BA%E5%99%A8%E5%B9%B3%E8%A1%A1%E7%82%B9%3F%22%7D%0A%20%20D%20--%3E%7C%E6%98%AF%7C%20E%5B%22%E5%85%88%E4%BC%98%E5%8C%96%E5%AD%97%E8%8A%82%EF%BC%8C%E5%86%8D%E8%B0%88%E6%8C%87%E4%BB%A4%22%5D%0A%20%20D%20--%3E%7C%E5%90%A6%7C%20F%5B%22%E7%AE%97%E5%8A%9B%E7%BB%91%E5%AE%9A%EF%BC%8C%E6%89%8D%E8%BD%AE%E5%88%B0%20FLOPs%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"把账算一次。解码单请求、三十二层、\\(h_{kv}=8\\)、\\(d=128\\)、fp16、上下文 \\(n=8192\\)：每个新 token 要读的 KV 是 \\(32\\times 2\\times 8\\times 128\\times 2\\,\\mathrm{B}\\times 8192\\approx 1\\,\\mathrm{GiB}\\)，按 \\(2\\,\\mathrm{TB/s}\\) 折算就是半毫秒级的纯搬运——这还没算权重。此时任何「少算一遍乘法」的改法在延迟表上都看不出来，因为瓶颈在 KV 的字节上；把 \\(h_{kv}\\) 从 8 压到 4，比把 GEMM 调快一倍有用得多。反过来，前填大 batch 时权重与 KV 都摊到大量 FLOPs 上，\\(I\\) 高过平衡点，同一份账指向完全不同的优化。这就是为什么内核调优的第一动作是记账，不是动手。",-1)),(e(),B(r,null,{default:E(()=>[i(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E8%A7%A3%E7%A0%81%2C%20%E5%B0%8F%20batch%22%5D%20--%3E%20D1%5B%22%E6%AF%8F%E6%AD%A5%E8%AF%BB%E5%85%A8%E9%87%8F%20KV%20%E7%BA%A6%201%20GiB%22%5D%0A%20%20D1%20--%3E%20D2%5B%22I%20%E4%BD%8E%E4%BA%8E%E5%B9%B3%E8%A1%A1%E7%82%B9%3A%20%E5%B8%A6%E5%AE%BD%E7%BB%91%E5%AE%9A%22%5D%0A%20%20D2%20--%3E%20D3%5B%22%E4%BC%98%E5%8C%96%E5%AD%97%E8%8A%82%3A%20%E5%8E%8B%20h_kv%20%2F%20GQA%22%5D%0A%20%20F%5B%22%E5%89%8D%E5%A1%AB%2C%20%E5%A4%A7%20batch%22%5D%20--%3E%20F1%5B%22%E6%9D%83%E9%87%8D%E4%B8%8E%20KV%20%E6%91%8A%E8%BF%9B%E6%B5%B7%E9%87%8F%20FLOPs%22%5D%0A%20%20F1%20--%3E%20F2%5B%22I%20%E9%AB%98%E4%BA%8E%E5%B9%B3%E8%A1%A1%E7%82%B9%3A%20%E7%AE%97%E5%8A%9B%E7%BB%91%E5%AE%9A%22%5D%0A%20%20F2%20--%3E%20F3%5B%22%E4%BC%98%E5%8C%96%E6%8C%87%E4%BB%A4%3A%20tile%20%E4%B8%8E%E6%95%B0%E5%80%BC%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p>错法有两个典型。一是拿着 MHA 时代的解码内核直接跑：每个查询头各自去读「自己的」K 和 V，同一段 KV 被 HBM 搬了好几遍，带宽账白花。二是以为合并访问只是「风格问题」：布局一转，一条事务拆成三十二条，实测带宽掉到峰值的一成——代码一行没错，速度全错。这两类错都藏在 FLOPs 表看不到的地方。</p><p><span class="marginnote">常见误区：初学者容易把优化等同于「让算得快」。在解码这种带宽绑定的场景里，少算一遍乘法一分钱不省，少搬一个字节立竿见影。所以第一动作永远是记账——这步到底搬了多少字节——而不是埋头改指令。</span></p><p><span class="marginnote">A100 的账：HBM 约 \\(1.5\\)–\\(2\\,\\mathrm{TB/s}\\)，L2 约 \\(40\\,\\mathrm{MiB}\\)、带宽高数倍，SM 内 SRAM 约 \\(19\\,\\mathrm{TB/s}\\)。上一课的 \\(O(n^2d^2/M)\\) 里的 \\(M\\) 就是这份 SRAM，快慢的数量级差全部来自层级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>记账给的是上界与方向，不给出数：占用率、流水线深度、延迟链都会让实测低于账面，基准方法论一课再立测量的规矩。L2 会骗人——小张量反复测时 KV 常驻 L2，带宽读数虚高，那也是基准课的题目；本课只负责把「数据应该住在哪一层」问对。访存模式随 batch、头数、布局与分页而翻转，账要按形状分别记，一张全局账本不存在。解码与前填的分工是调度器的活，本课只管内核这一段。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>算术强度对上机器平衡点，先判断是带宽绑定还是算力绑定，再决定优化哪头。</li><li>三本账：必搬字节按算法定，合并访问按布局定，复用层级按驻留位置定。</li><li>解码小 batch 是 KV 字节的账；\\(h_{kv}\\) 减半胜过 GEMM 快一倍。</li><li>布局决定合并访问能否成立，转置布局能让带宽掉一个数量级。</li><li>复用要落在确定性层级（寄存器、SRAM），不赌 L2。</li><li>出处：Williams et al., <em>Roofline</em>, CACM 2009；IO 分析口径据 Dao et al., <em>FlashAttention</em>, 2022。</li></ul>',7))])}const b=n(d,[["render",h]]);export{f as __pageData,b as default};
